    monkeypatch.setenv("GRID_HOME", str(tmp_path))
    runtime.init_grid_config(name="home", port=8090)
    monkeypatch.setattr(
        cli.grid.runtime, "stop_grid",
        lambda cfg: runtime.StopOutcome(run_records.Teardown(survivor=777, is_group=True), False),
    )

